async function loadAttachmentBadges(_notes: NoteSearchResult[]): Promise<void> {
  if (!state) return;
  const ar = getAttachmentsRepo();
  if (!ar) return;

  const counts = await fetchAttachmentCounts(state.host, state.token, ar.owner, ar.repo);
  document.querySelectorAll<HTMLElement>('.attachment-count-badge').forEach(badge => {
    const key = `${badge.dataset.owner}/${badge.dataset.repo}/${badge.dataset.issue}`;
    const count = counts.get(key);
    if (count) badge.textContent = ` 📎${count}`;
  });
}

function showRepoPicker(
  notesList: NoteSearchResult[],
  opts?: { title?: string; onPick?: (owner: string, repo: string) => void; excludeRepos?: Set<string> },
): void {
  // Remove existing picker if any
  document.getElementById('repo-picker-overlay')?.remove();

  const onPick = opts?.onPick ?? openNewNote;
  const title = opts?.title ?? 'Select repository';

  // Extract unique owner/repo pairs, sorted with default repo first
  const repoSet = new Map<string, { owner: string; repo: string }>();
  // Always include the default repo if configured (unless excluded — e.g. it's
  // one of the notes being moved, and moving to its own repo is a no-op)
  const defaultRepo = getDefaultRepo();
  if (defaultRepo && !opts?.excludeRepos?.has(defaultRepo)) {
    const [defOwner, defRepo] = defaultRepo.split('/');
    repoSet.set(defaultRepo, { owner: defOwner, repo: defRepo });
  }
  for (const n of notesList) {
    const key = `${n.owner}/${n.repo}`;
    if (opts?.excludeRepos?.has(key)) continue;
    if (!repoSet.has(key)) repoSet.set(key, { owner: n.owner, repo: n.repo });
  }
  const sortedRepos = Array.from(repoSet.entries()).sort((a, b) => {
    if (defaultRepo) {
      if (a[0] === defaultRepo) return -1;
      if (b[0] === defaultRepo) return 1;
    }
    return a[0].localeCompare(b[0]);
  });

  const overlay = document.createElement('div');
  overlay.id = 'repo-picker-overlay';
  overlay.innerHTML = `
    <div class="repo-picker">
      <h2>${escapeHtml(title)}</h2>
      <div class="repo-list">
        ${sortedRepos.map(([key, r]) => `
          <button class="repo-option" data-owner="${escapeAttr(r.owner)}" data-repo="${escapeAttr(r.repo)}">${escapeHtml(key)}</button>
        `).join('')}
      </div>
      <div class="repo-other">
        <label>Other
          <input type="text" id="repo-other-input" placeholder="owner/repo" />
        </label>
        <button id="repo-other-go">Go</button>
      </div>
    </div>
  `;

  app.appendChild(overlay);

  // Close on overlay background click
  overlay.addEventListener('click', (e) => {
    if (e.target === overlay) overlay.remove();
  });

  // Close on Escape
  const onKey = (e: KeyboardEvent) => {
    if (e.key === 'Escape') { overlay.remove(); document.removeEventListener('keydown', onKey); }
  };
  document.addEventListener('keydown', onKey);

  // Repo buttons
  overlay.querySelectorAll('.repo-option').forEach(btn => {
    btn.addEventListener('click', () => {
      const owner = (btn as HTMLElement).dataset.owner!;
      const repo = (btn as HTMLElement).dataset.repo!;
      overlay.remove();
      document.removeEventListener('keydown', onKey);
      onPick(owner, repo);
    });
  });

  // Other input
  const goBtn = document.getElementById('repo-other-go')!;
  const otherInput = document.getElementById('repo-other-input') as HTMLInputElement;

  const submitOther = () => {
    const val = otherInput.value.trim();
    const parts = val.split('/');
    if (parts.length !== 2 || !parts[0] || !parts[1]) {
      otherInput.classList.add('error');
      return;
    }
    overlay.remove();
    document.removeEventListener('keydown', onKey);
    onPick(parts[0], parts[1]);
  };

  goBtn.addEventListener('click', submitOther);
  otherInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') submitOther();
  });
}

async function openNewNote(owner: string, repo: string): Promise<void> {
  if (!state) return;
  if (!await repoExists(state.host, state.token, owner, repo)) {
    logError(`Auth: Repo validation failed for ${owner}/${repo}`);
    alert(`Repository "${owner}/${repo}" not found. Check the owner and repo name.`);
    return;
  }
  newNoteTarget = { owner, repo };
  activeNoteKey = null;
  currentScreen = 'edit';
  currentEditKey = null;
  replaceRoute({ screen: 'new', owner, repo });
  renderEditor(DEFAULT_NEW_TITLE, DEFAULT_NEW_BODY, null);
}

// ---------------------------------------------------------------------------
// Move Note
//
// There is no delete-issue endpoint in GitHub's REST v3 API (GraphQL's
// deleteIssue mutation needs admin rights most collaborators won't have), so
// "move" is copy-then-close: create the note at the destination with a
// backlink to the source, copy its attachments, then close the source with a
// forward footer. Nothing is ever destroyed — the worst outcome of any
// failure partway through is a harmless duplicate, never lost data. That
// invariant is what allows every step below to fail forward instead of
// rolling back.
// ---------------------------------------------------------------------------

interface NoteRef { owner: string; repo: string; number: number; title?: string }

const MOVE_FROM_MARKER = '<!-- notehub:moved-from -->';
const MOVE_TO_MARKER = '<!-- notehub:moved-to -->';

function movedFromFooter(host: string, src: NoteRef): string {
  return `\n\n---\n${MOVE_FROM_MARKER}\n> Moved from [${src.owner}/${src.repo}#${src.number}](${issueUrl(host, src.owner, src.repo, src.number)})`;
}

function movedToFooter(host: string, dest: NoteRef): string {
  return `\n\n---\n${MOVE_TO_MARKER}\n> Moved to [${dest.owner}/${dest.repo}#${dest.number}](${issueUrl(host, dest.owner, dest.repo, dest.number)})`;
}

function hasMoveMarker(body: string): boolean {
  return body.includes(MOVE_FROM_MARKER) || body.includes(MOVE_TO_MARKER);
}

type MoveOutcome =
  | { status: 'moved'; src: NoteRef; dest: NoteSearchResult; attachmentsCopied: number }
  | { status: 'partial'; src: NoteRef; dest: NoteSearchResult; stage: 'attachments' | 'close';
      message: string; attachmentsCopied: number; attachmentsFailed: string[] }
  | { status: 'failed'; src: NoteRef; stage: 'fetch' | 'create'; message: string }
  | { status: 'skipped'; src: NoteRef; reason: 'aborted' };

/** fetchAttachmentBlob has no retry of its own (unlike apiFetch-backed calls) —
 * it's also the largest-payload call in the move pipeline, so give it one
 * local retry here rather than changing the shared function's behavior for
 * every caller. */
async function fetchAttachmentBlobRetried(
  host: string, token: string, owner: string, repo: string, path: string,
): Promise<{ blob: Blob; filename: string }> {
  try {
    return await fetchAttachmentBlob(host, token, owner, repo, path);
  } catch {
    return await fetchAttachmentBlob(host, token, owner, repo, path);
  }
}

async function moveOneNote(
  src: NoteSearchResult,
  dest: { owner: string; repo: string },
  attachRepo: { owner: string; repo: string } | null,
  knownAttachmentCount: number,
  onProgress: (msg: string) => void,
): Promise<MoveOutcome> {
  const srcRef: NoteRef = { owner: src.owner, repo: src.repo, number: src.number, title: src.title };
  if (!state) return { status: 'failed', src: srcRef, stage: 'fetch', message: 'Not authenticated' };
  const host = state.host, token = state.token;

  let fresh: GitHubIssue;
  try {
    onProgress(`Reading #${src.number}: ${src.title}`);
    fresh = await getNote(host, token, src.owner, src.repo, src.number);
  } catch (err) {
    return { status: 'failed', src: srcRef, stage: 'fetch', message: err instanceof Error ? err.message : String(err) };
  }

  let created: GitHubIssue;
  try {
    onProgress(`Creating in ${dest.owner}/${dest.repo}: ${fresh.title}`);
    const destBody = (fresh.body ?? '') + movedFromFooter(host, srcRef);
    created = await createNote(host, token, dest.owner, dest.repo, fresh.title, destBody);
  } catch (err) {
    return { status: 'failed', src: srcRef, stage: 'create', message: err instanceof Error ? err.message : String(err) };
  }
  const destNote: NoteSearchResult = { ...created, owner: dest.owner, repo: dest.repo };

  let attachmentsCopied = 0;
  const attachmentsFailed: string[] = [];
  if (attachRepo && knownAttachmentCount > 0) {
    let files;
    try {
      onProgress(`Checking attachments for #${src.number}`);
      files = await listAttachments(host, token, attachRepo.owner, attachRepo.repo, src.owner, src.repo, src.number);
    } catch (err) {
      return {
        status: 'partial', src: srcRef, dest: destNote, stage: 'attachments',
        message: `Could not list attachments: ${err instanceof Error ? err.message : String(err)}`,
        attachmentsCopied, attachmentsFailed,
      };
    }
    for (const file of files) {
      try {
        onProgress(`Copying attachment ${file.name}`);
        const { blob } = await fetchAttachmentBlobRetried(host, token, attachRepo.owner, attachRepo.repo, file.path);
        const base64 = await blobToBase64(blob);
        await uploadAttachment(host, token, attachRepo.owner, attachRepo.repo, dest.owner, dest.repo, created.number, file.name, base64);
        attachmentsCopied++;
      } catch (err) {
        logError(`Move: attachment copy failed for ${file.name}: ${err instanceof Error ? err.message : String(err)}`);
        attachmentsFailed.push(file.name);
      }
    }
    if (attachmentsFailed.length > 0) {
      return {
        status: 'partial', src: srcRef, dest: destNote, stage: 'attachments',
        message: `${attachmentsFailed.length} of ${files.length} attachment(s) failed to copy`,
        attachmentsCopied, attachmentsFailed,
      };
    }
  }

  const srcBody = fresh.body ?? '';
  const closedBody = hasMoveMarker(srcBody) ? srcBody : srcBody + movedToFooter(host, destNote);
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      onProgress(`Closing source #${src.number}`);
      const closed = await updateNote(host, token, src.owner, src.repo, src.number, { body: closedBody, state: 'closed' });
      if (closed.state !== 'closed') throw new Error('note was not closed');
      return { status: 'moved', src: srcRef, dest: destNote, attachmentsCopied };
    } catch (err) {
      if (attempt === 1) {
        return {
          status: 'partial', src: srcRef, dest: destNote, stage: 'close',
          message: err instanceof Error ? err.message : String(err),
          attachmentsCopied, attachmentsFailed,
        };
      }
    }
  }
  // Unreachable — the loop above always returns.
  return { status: 'moved', src: srcRef, dest: destNote, attachmentsCopied };
}

/** Sequential by design: GitHub applies secondary rate limits to content-creating
 * requests, and each note is a multi-step pipeline whose progress messages need
 * to stay honest about "note i of N" — a concurrent pool would blur that. */
async function moveNotes(
  sources: NoteSearchResult[],
  dest: { owner: string; repo: string },
  attachmentCounts: Map<string, number> | null,
  onStep: (i: number, total: number, msg: string) => void,
  shouldStop: () => boolean,
): Promise<MoveOutcome[]> {
  if (!state) return [];
  const attachRepo = getAttachmentsRepo();
  const outcomes: MoveOutcome[] = [];
  let aborted = false;

  for (let i = 0; i < sources.length; i++) {
    const src = sources[i];
    const srcRef: NoteRef = { owner: src.owner, repo: src.repo, number: src.number, title: src.title };

    if (aborted || (i > 0 && shouldStop())) {
      outcomes.push({ status: 'skipped', src: srcRef, reason: 'aborted' });
      continue;
    }

    const knownCount = attachmentCounts?.get(noteKey(src)) ?? 0;
    const outcome = await moveOneNote(src, dest, attachRepo, knownCount, msg => onStep(i, sources.length, msg));
    outcomes.push(outcome);

    if (outcome.status === 'failed') {
      // 401 = dead token, 403 = permission or secondary rate limit — neither
      // will resolve itself for the remaining notes in this batch.
      const status = /^GitHub API (\d+):/.exec(outcome.message)?.[1];
      if (status === '401' || status === '403') aborted = true;
    }

    if (i < sources.length - 1) await new Promise(r => setTimeout(r, 300));
  }
  return outcomes;
}

function showMoveProgress(total: number): { update(i: number, msg: string): void; stopRequested(): boolean; close(): void } {
  document.getElementById('move-progress-overlay')?.remove();
  let stopFlag = false;

  const overlay = document.createElement('div');
  overlay.id = 'move-progress-overlay';
  overlay.innerHTML = `
    <div class="move-progress-dialog">
      <h3 id="move-progress-title">Moving 1 of ${total}...</h3>
      <p id="move-progress-detail"></p>
      <div class="move-progress-actions">
        <button id="move-progress-stop">Stop after this note</button>
      </div>
    </div>
  `;
  document.body.appendChild(overlay);

  const stopBtn = overlay.querySelector('#move-progress-stop') as HTMLButtonElement;
  stopBtn.addEventListener('click', () => {
    stopFlag = true;
    stopBtn.disabled = true;
    stopBtn.textContent = 'Stopping after current note...';
  });

  return {
    update(i: number, msg: string): void {
      const titleEl = document.getElementById('move-progress-title');
      const detailEl = document.getElementById('move-progress-detail');
      if (titleEl) titleEl.textContent = `Moving ${i + 1} of ${total}...`;
      if (detailEl) detailEl.textContent = msg;
    },
    stopRequested: () => stopFlag,
    close: () => overlay.remove(),
  };
}

function showMoveReport(outcomes: MoveOutcome[], dest: { owner: string; repo: string }): void {
  if (!state) return;
  document.getElementById('move-report-overlay')?.remove();

  const movedCount = outcomes.filter(o => o.status === 'moved').length;
  const total = outcomes.length;
  const header = `Moved ${movedCount} of ${total} note${total !== 1 ? 's' : ''} to ${dest.owner}/${dest.repo}`;

  if (movedCount === total) {
    const toast = document.createElement('div');
    toast.id = 'move-report-overlay';
    toast.className = 'move-report-toast';
    toast.textContent = header;
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 1500);
    return;
  }

  const rows = outcomes.filter(o => o.status !== 'moved').map(o => {
    const srcLink = `<a href="${escapeAttr(issueUrl(state!.host, o.src.owner, o.src.repo, o.src.number))}" target="_blank">${escapeHtml(o.src.owner)}/${escapeHtml(o.src.repo)}#${o.src.number}</a>`;
    if (o.status === 'partial') {
      const destLink = `<a href="${escapeAttr(issueUrl(state!.host, o.dest.owner, o.dest.repo, o.dest.number))}" target="_blank">${escapeHtml(o.dest.owner)}/${escapeHtml(o.dest.repo)}#${o.dest.number}</a>`;
      const remedy = o.stage === 'close'
        ? 'Copy succeeded, but the source could not be closed — close it manually.'
        : 'Note copied, but not all attachments made it — check the destination and re-attach if needed.';
      return `<div class="move-report-row move-report-partial"><strong>${srcLink} → ${destLink}</strong><p>${escapeHtml(remedy)} (${escapeHtml(o.message)})</p></div>`;
    }
    if (o.status === 'failed') {
      return `<div class="move-report-row move-report-failed"><strong>${srcLink}</strong><p>Failed at ${o.stage}: ${escapeHtml(o.message)}. Source untouched.</p></div>`;
    }
    return `<div class="move-report-row move-report-skipped"><strong>${srcLink}</strong><p>Not attempted — batch stopped early. Source untouched.</p></div>`;
  }).join('');

  const reportText = [header, '', ...outcomes.map(o => {
    if (o.status === 'moved') return `MOVED    ${noteKey(o.src)} -> ${noteKey(o.dest)}`;
    if (o.status === 'partial') return `PARTIAL(${o.stage})  ${noteKey(o.src)} -> ${noteKey(o.dest)}: ${o.message}`;
    if (o.status === 'failed') return `FAILED(${o.stage})   ${noteKey(o.src)}: ${o.message}`;
    return `SKIPPED  ${noteKey(o.src)}`;
  })].join('\n');

  const overlay = document.createElement('div');
  overlay.id = 'move-report-overlay';
  overlay.innerHTML = `
    <div class="move-report-dialog">
      <h3>${escapeHtml(header)}</h3>
      <div class="move-report-rows">${rows}</div>
      <div class="move-report-actions">
        <button id="move-report-copy">Copy report</button>
        <button id="move-report-close">Close</button>
      </div>
    </div>
  `;
  document.body.appendChild(overlay);
  overlay.querySelector('#move-report-close')!.addEventListener('click', () => overlay.remove());
  overlay.querySelector('#move-report-copy')!.addEventListener('click', () => { void copyText(reportText); });
  overlay.addEventListener('click', (e) => { if (e.target === overlay) overlay.remove(); });
}

async function runMove(selected: NoteSearchResult[], destOwner: string, destRepo: string): Promise<void> {
  if (!state || selected.length === 0) return;

  if (!await repoExists(state.host, state.token, destOwner, destRepo)) {
    alert(`Repository "${destOwner}/${destRepo}" not found. Check the owner and repo name.`);
    return;
  }

  const ar = getAttachmentsRepo();
  let attachmentCounts: Map<string, number> | null = null;
  if (ar) {
    try {
      attachmentCounts = await fetchAttachmentCounts(state.host, state.token, ar.owner, ar.repo);
    } catch {
      attachmentCounts = null;
    }
  }

  const progress = showMoveProgress(selected.length);
  const outcomes = await moveNotes(
    selected,
    { owner: destOwner, repo: destRepo },
    attachmentCounts,
    (i, _total, msg) => progress.update(i, msg),
    () => progress.stopRequested(),
  );
  progress.close();

  for (const outcome of outcomes) {
    if (outcome.status === 'moved' || outcome.status === 'partial') overlayAdd(outcome.dest);
    if (outcome.status === 'moved') overlayRemove(outcome.src);
  }

  showMoveReport(outcomes, { owner: destOwner, repo: destRepo });
  void showNoteList();
}

async function openNote(owner: string, repo: string, number: number): Promise<void> {
  if (!state) return;
  currentScreen = 'edit';
  const key = `${owner}/${repo}/${number}`;
  currentEditKey = key;
  replaceRoute({ screen: 'edit', owner, repo, number });

  // If we already have a buffer for this note, re-render it.
  // We must always call renderEditor (not the onBufferActivated shortcut) so that
  // veditor.createEditor runs, which cancels any pending auto-save timer from the
  // previous note and resets veditor's buffer manager.  Skipping createEditor leaves
  // veditor pointing at the old buffer; if its auto-save then fires it reads the old
  // content but resolves the save target via activeNoteKey (now pointing here),
  // overwriting this note with the previous one's content.
  if (noteBuffers.has(key)) {
    activeNoteKey = key;
    const buf = noteBuffers.get(key)!;
    renderEditor(buf.note.title, buf.originalBody, buf);
    void checkFreshness('switch');
    return;
  }

  app.innerHTML = `<div class="editor-screen"><p>Loading note #${number}...</p></div>`;

  try {
    logInfo(`Note: Opening note #${number} from ${owner}/${repo}`);
    const note = await getNote(state.host, state.token, owner, repo, number);
    logInfo(`Note: Loaded note #${number}: "${note.title}"`);
    const noteResult = { ...note, owner, repo };
    const buf = createNoteBuffer(noteResult, note.body ?? '', note.title, note.updated_at);
    noteBuffers.set(key, buf);
    activeNoteKey = key;
    renderEditor(note.title, buf.originalBody, buf);
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    logError(`Note: Failed to load note #${number}: ${msg}`);
    app.innerHTML = `<div class="editor-screen"><p class="error">Failed to load note: ${msg}</p></div>`;
  }
}

/** Update header chrome and URL when a buffer becomes active (without re-rendering the editor). */
function onBufferActivated(key: string, buf: NoteBuffer): void {
  if (activeNoteKey === key) return;
  activeNoteKey = key;
  currentEditKey = key;
  const note = buf.note;
  replaceRoute({ screen: 'edit', owner: note.owner, repo: note.repo, number: note.number });

  titleHandle?.setValue(note.title);

  const numEl = document.getElementById('note-number');
  if (numEl) numEl.innerHTML = noteNumberHtml(state!.host, note.owner, note.repo, note.number);

  // Sync attachment panel state to incoming buffer
  currentAttachments = buf.attachments;
  selectedAttachmentIndex = buf.selectedAttachmentIndex;
  multiSelectedAttachments = buf.multiSelectedAttachments;
  if (document.getElementById('attachment-panel')) {
    closeAttachmentPanel();
  }

  // A freshness banner belongs to the buffer that was active when it appeared;
  // this path doesn't re-render the editor screen, so it wouldn't otherwise be
  // cleared when switching away from that buffer.
  hideFreshnessBanner();
  void checkFreshness('switch');
}

// ---------------------------------------------------------------------------
// Freshness checks — catch a stale note *before* it becomes a save conflict.
//
// This does not replace the save-path conflict check above; it just shrinks the
// window in which a conflict can happen by refreshing the active buffer earlier:
//   - 'edit'  — the buffer just went clean->dirty (see onDirty), and it's been
//               more than STALE_WINDOW_MS since we last confirmed it was current.
//               This is the case where the window never lost focus — e.g. editing
//               continuously on machine A while machine B saved in the background.
//   - 'focus' — the window/tab just became visible. No staleness gate: switching
//               to this window shortly after another machine saved is the most
//               common case, and re-checking every time is cheap and immediate.
//   - 'switch'— veditor (or notehub's own re-open-an-existing-buffer path) just
//               activated this buffer. No staleness gate, for the same reason.
// A clean buffer is refreshed silently; a dirty one gets a dismissible banner
// instead — never a modal, and never a nag on network failure.
// ---------------------------------------------------------------------------

function isBufferDirty(buf: NoteBuffer): boolean {
  const bodyDirty = veditor.getEditorContent() !== buf.originalBody;
  const titleDirty = (titleHandle?.getValue() ?? '').trim() !== buf.originalTitle;
  return bodyDirty || titleDirty;
}

async function checkFreshness(reason: 'edit' | 'focus' | 'switch'): Promise<void> {
  if (!state || freshnessCheckInFlight || saveInFlight) return;
  const key = activeNoteKey;
  const buf = activeBuffer();
  if (!key || !buf) return; // no active note (list/settings screen, or an unsaved new note)

  if (reason === 'edit' && Date.now() - buf.lastFetchedAt < STALE_WINDOW_MS) return;

  freshnessCheckInFlight = true;
  try {
    const fresh = await getNote(state.host, state.token, buf.note.owner, buf.note.repo, buf.note.number);

    // The user may have saved, switched buffers, or navigated to the list while
    // this was in flight; only apply the result if it's still the same buffer.
    if (activeNoteKey !== key || noteBuffers.get(key) !== buf) return;

    buf.lastFetchedAt = Date.now();
    if (!buf.loadedUpdatedAt || fresh.updated_at === buf.loadedUpdatedAt) return; // not stale

    const canSilentRefresh = typeof veditor.setEditorContent === 'function';
    if (!isBufferDirty(buf) && canSilentRefresh) {
      applyRefresh(buf, fresh);
      return;
    }

    if (buf.staleDismissedAt === fresh.updated_at) return; // already warned + dismissed for this version
    showFreshnessBanner(buf, fresh);
  } catch (err) {
    // Never nag on a failed check (network blip, note deleted upstream, etc) —
    // the save-path conflict check remains the backstop of record.
    logWarn(`Note: Freshness check (${reason}) failed for #${buf.note.number}: ${err instanceof Error ? err.message : err}`);
  } finally {
    freshnessCheckInFlight = false;
  }
}

/** Apply a confirmed-fresh remote copy to the active buffer, in place. */
function applyRefresh(buf: NoteBuffer, fresh: GitHubIssue): void {
  const isStillActive = activeNoteKey !== null && noteBuffers.get(activeNoteKey) === buf;
  if (isStillActive && typeof veditor.setEditorContent === 'function') {
    veditor.setEditorContent(fresh.body ?? '');
    titleHandle?.setValue(fresh.title);
  }
  buf.originalBody = fresh.body ?? '';
  buf.originalTitle = fresh.title;
  buf.loadedUpdatedAt = fresh.updated_at;
  buf.note = { ...fresh, owner: buf.note.owner, repo: buf.note.repo };
  buf.lastFetchedAt = Date.now();
  buf.staleDismissedAt = null;
  hideFreshnessBanner();
  if (isStillActive) showStatus('Refreshed from upstream');
}

function hideFreshnessBanner(): void {
  document.getElementById('freshness-banner')?.remove();
}

function showFreshnessBanner(buf: NoteBuffer, fresh: GitHubIssue): void {
  hideFreshnessBanner();
  const screen = document.querySelector('.editor-screen');
  const container = document.getElementById('editor-container');
  if (!screen || !container) return;

  const canSilentRefresh = typeof veditor.setEditorContent === 'function';
  const bar = document.createElement('div');
  bar.id = 'freshness-banner';
  bar.className = 'freshness-banner';
  bar.innerHTML = `
    <span>This note changed upstream.</span>
    <button id="freshness-reload">Reload</button>
    <button id="freshness-keep">Keep mine</button>
  `;
  screen.insertBefore(bar, container);

  bar.querySelector('#freshness-reload')!.addEventListener('click', () => {
    if (canSilentRefresh) {
      applyRefresh(buf, fresh);
    } else {
      // Belt-and-braces fallback for an old cached veditor build without
      // setEditorContent — this should only matter if notehub was deployed
      // ahead of veditor.web. There's no in-place way to reload without it.
      location.reload();
    }
  });
  bar.querySelector('#freshness-keep')!.addEventListener('click', () => {
    buf.staleDismissedAt = fresh.updated_at;
    hideFreshnessBanner();
  });
}

/** Focus/visibility trigger, debounced so a focus+visibilitychange pair (or rapid
 * alt-tabbing) doesn't fire the check twice in quick succession. */
function scheduleFocusFreshnessCheck(): void {
  if (currentScreen !== 'edit' || !activeNoteKey || newNoteTarget || document.hidden) return;
  const now = Date.now();
  if (now - lastFocusFreshnessCheckAt < FOCUS_DEBOUNCE_MS) return;
  lastFocusFreshnessCheckAt = now;
  void checkFreshness('focus');
}

function makeSaveCallback(getBuf: () => NoteBuffer | null): () => Promise<void> {
  return async () => {
    if (!state) return;

    const body = veditor.getEditorContent();
    const title = (titleHandle?.getValue() ?? '').trim();
    const buf = getBuf();

    // Creating a new note
    if (!buf && newNoteTarget) {
      if (!title) { showStatus('Title required', true); return; }
      try {
        showStatus('Creating...');
        logInfo(`Note: Creating new note in ${newNoteTarget.owner}/${newNoteTarget.repo}`);
        const created = await createNote(state.host, state.token, newNoteTarget.owner, newNoteTarget.repo, title, body);
        logInfo(`Note: Created new note: #${created.number}`);
        const noteResult = { ...created, owner: newNoteTarget.owner, repo: newNoteTarget.repo };
        overlayAdd(noteResult);
        newNoteTarget = null;

        const key = `${noteResult.owner}/${noteResult.repo}/${noteResult.number}`;
        const newBuf = createNoteBuffer(noteResult, created.body ?? '', created.title, created.updated_at);
        noteBuffers.set(key, newBuf);
        activeNoteKey = key;
        currentEditKey = key;
        replaceRoute({ screen: 'edit', owner: noteResult.owner, repo: noteResult.repo, number: noteResult.number });

        const numEl = document.getElementById('note-number');
        if (numEl) numEl.innerHTML = noteNumberHtml(state.host, noteResult.owner, noteResult.repo, noteResult.number);
        showStatus('Created');
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        logError(`Note: Failed to create note: ${msg}`);
        showStatus(`Create failed: ${msg}`, true);
      }
      return;
    }

    if (!buf) return;

    const data: { title?: string; body?: string } = {};
    if (body !== buf.originalBody) data.body = body;
    if (title !== buf.originalTitle) data.title = title;

    if (Object.keys(data).length === 0) { showStatus('No changes'); return; }

    saveInFlight = true;
    try {
      showStatus('Saving...');
      logInfo(`Note: Save initiated for #${buf.note.number}`);

      const fresh = await getNote(state.host, state.token, buf.note.owner, buf.note.repo, buf.note.number);
      buf.lastFetchedAt = Date.now(); // we just talked to the server, regardless of outcome below
      if (buf.loadedUpdatedAt && fresh.updated_at !== buf.loadedUpdatedAt) {
        logWarn(`Note: Remote conflict detected for #${buf.note.number}; awaiting user choice`);
        const overwrite = await showConflictDialog();
        if (!overwrite) { logInfo(`Note: Save cancelled due to conflict`); showStatus('Save cancelled'); return; }
        logWarn(`Note: Remote conflict for #${buf.note.number}; user chose to overwrite`);
      }

      const updated = await updateNote(state.host, state.token, buf.note.owner, buf.note.repo, buf.note.number, data);
      logInfo(`Note: Save successful for #${buf.note.number}: "${updated.title}"`);
      buf.originalBody = updated.body ?? '';
      buf.originalTitle = updated.title;
      buf.loadedUpdatedAt = updated.updated_at;
      buf.note = { ...updated, owner: buf.note.owner, repo: buf.note.repo };
      buf.lastFetchedAt = Date.now();
      buf.staleDismissedAt = null;
      hideFreshnessBanner();
      showStatus('Saved');
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      logError(`Note: Save failed for #${buf.note.number}: ${msg}`);
      showStatus(`Save failed: ${msg}`, true);
    } finally {
      saveInFlight = false;
    }
  };
}

async function loadDocument(id: string): Promise<{ content: string; label: string; callbacks: import('./veditor').VEditorCallbacks }> {
  if (!state) throw new Error('Not authenticated');

  if (noteBuffers.has(id)) {
    const buf = noteBuffers.get(id)!;
    return {
      content: buf.originalBody,
      label: buf.note.title,
      callbacks: makeBufferCallbacks(() => noteBuffers.get(id) ?? null),
    };
  }

  const parts = id.split('/');
  if (parts.length !== 3) throw new Error(`Invalid document id: ${id}`);
  const [owner, repo, numStr] = parts;
  const number = parseInt(numStr, 10);

  logInfo(`Note: Loading document ${id} for new buffer`);
  const note = await getNote(state.host, state.token, owner, repo, number);
  const noteResult = { ...note, owner, repo };
  const buf = createNoteBuffer(noteResult, note.body ?? '', note.title, note.updated_at);
  noteBuffers.set(id, buf);

  return {
    content: buf.originalBody,
    label: note.title,
    callbacks: makeBufferCallbacks(() => noteBuffers.get(id) ?? null),
  };
}

function makeBufferCallbacks(getBuf: () => NoteBuffer | null): import('./veditor').VEditorCallbacks {
  return {
    onSave: makeSaveCallback(getBuf),
    onQuit: () => {
      noteBuffers.clear();
      navigate({ screen: 'list' });
    },
    isAppDirty: () => {
      const buf = getBuf();
      if (!buf) return false;
      return titleHandle?.getValue().trim() !== buf.originalTitle;
    },
    onBufferSwitch: (newId: string) => {
      const buf = noteBuffers.get(newId);
      if (buf) onBufferActivated(newId, buf);
    },
    onDirty: () => { void checkFreshness('edit'); },
    onListDocuments: async () =>
      lastFetchedNotesList.map(n => ({ id: `${n.owner}/${n.repo}/${n.number}`, label: n.title })),
    onLoadDocument: loadDocument,
  };
}

type PickerMode = 'search' | 'throw' | 'kick';

const PICKER_LABELS: Record<PickerMode, { badge: string; placeholder: string; confirmHint: string }> = {
  search: {
    badge: '',
    placeholder: 'Search all notes...',
    confirmHint: '<span><kbd>Enter</kbd> Open</span><span><kbd>Ctrl+Enter</kbd> New tab</span>',
  },
  throw: {
    badge: 'Throw',
    placeholder: 'Throw a note into a new tab...',
    confirmHint: '<span><kbd>Enter</kbd> Open in new tab</span>',
  },
  kick: {
    badge: 'Kick',
    placeholder: 'Kick current note out, load another...',
    confirmHint: '<span><kbd>Enter</kbd> Swap</span>',
  },
};

function noteRoute(note: { owner: string; repo: string; number: number }): Route {
  return { screen: 'edit', owner: note.owner, repo: note.repo, number: note.number };
}

function isActiveNote(note: { owner: string; repo: string; number: number }): boolean {
  const buf = activeBuffer();
  return !!buf && buf.note.owner === note.owner && buf.note.repo === note.repo && buf.note.number === note.number;
}

async function throwNote(note: NoteSearchResult): Promise<void> {
  if (isActiveNote(note)) await veditor.requestSave();
  window.open(`${location.pathname}${buildHash(noteRoute(note))}`, '_blank');
  showStatus(`Opened "${note.title}" in new tab`);
}

async function kickCurrentAndLoad(note: NoteSearchResult): Promise<void> {
  const chosenRoute = noteRoute(note);
  const selfKick = isActiveNote(note);
  await veditor.requestSave();
  const buf = activeBuffer();
  const failed = !buf
    || veditor.getEditorContent() !== buf.originalBody
    || (titleHandle?.getValue() ?? '').trim() !== buf.originalTitle;
  if (failed) { showStatus('Save failed — kick cancelled', true); return; }
  window.open(`${location.pathname}${buildHash(noteRoute(buf.note))}`, '_blank');
  if (selfKick) return; // second view of the same note — keep editing in place
  navigate(chosenRoute);
}

function showNotePicker(mode: PickerMode = 'search'): void {
  if (document.getElementById('global-search-overlay')) return;
  if (!state) return;

  let allNotes: NoteSearchResult[] = [];
  let gsRegexMode = false;
  let gsSelectedIndex = 0;
  let gsDebounce: ReturnType<typeof setTimeout> | null = null;
  let currentMatches: SearchMatch[] = [];
  const labels = PICKER_LABELS[mode];

  const overlay = document.createElement('div');
  overlay.id = 'global-search-overlay';
  overlay.className = `global-search-overlay${mode !== 'search' ? ` mode-${mode}` : ''}`;
  overlay.innerHTML = `
    <div class="global-search-card">
      <div class="global-search-header">
        ${labels.badge ? `<span class="global-search-badge">${labels.badge}</span>` : ''}
        <input id="gs-input" class="global-search-input" type="text" placeholder="${labels.placeholder}" autocomplete="off" spellcheck="false" />
        <button id="gs-regex" class="search-regex-toggle" title="Toggle regex (Ctrl+R)">.*</button>
        <span id="gs-count" class="search-count"></span>
      </div>
      <div id="gs-results" class="global-search-results">
        <p class="global-search-status">Loading notes...</p>
      </div>
      <div class="global-search-footer">
        <span><kbd>Tab</kbd> Results</span>
        <span><kbd>j</kbd><kbd>k</kbd> Navigate</span>
        ${labels.confirmHint}
        <span><kbd>Ctrl+R</kbd> Regex</span>
        <span><kbd>Esc</kbd> Close</span>
      </div>
    </div>
  `;
  document.body.appendChild(overlay);

  const input = document.getElementById('gs-input') as HTMLInputElement;
  const resultsEl = document.getElementById('gs-results')!;
  const countEl = document.getElementById('gs-count')!;
  const regexBtn = document.getElementById('gs-regex')!;

  input.focus();

  function dismiss(): void {
    overlay.remove();
    veditor?.focusEditor();
  }

  function updateRegexBtn(): void {
    regexBtn.classList.toggle('active', gsRegexMode);
  }

  function updateSelection(): void {
    resultsEl.querySelectorAll('.global-search-result').forEach((row, i) => {
      row.classList.toggle('selected', i === gsSelectedIndex);
    });
    resultsEl.querySelector('.global-search-result.selected')?.scrollIntoView({ block: 'nearest' });
  }

  function renderResults(matches: SearchMatch[]): void {
    currentMatches = matches;
    gsSelectedIndex = 0;
    if (matches.length === 0) {
      resultsEl.innerHTML = '<p class="global-search-status">No matches.</p>';
      return;
    }
    resultsEl.innerHTML = matches.map((m, i) => `
      <div class="global-search-result${i === 0 ? ' selected' : ''}" data-index="${i}">
        <span class="global-search-result-title">${escapeHtml(m.note.title)}</span>
        <span class="global-search-result-repo">${escapeHtml(m.note.repo)}</span>
        <span class="global-search-result-context search-context">${m.context}</span>
      </div>
    `).join('');

    resultsEl.querySelectorAll('.global-search-result').forEach(row => {
      const idx = parseInt((row as HTMLElement).dataset.index!, 10);
      row.addEventListener('mousemove', () => {
        if (gsSelectedIndex !== idx) { gsSelectedIndex = idx; updateSelection(); }
      });
      row.addEventListener('click', (e) => {
        gsSelectedIndex = idx;
        confirmSelection((e as MouseEvent).ctrlKey || (e as MouseEvent).metaKey);
      });
    });
  }

  function showAllNotes(): void {
    countEl.textContent = `${allNotes.length} note${allNotes.length !== 1 ? 's' : ''}`;
    countEl.classList.remove('error');
    renderResults(allNotes.map((note, index) => ({ note, index, context: '' })));
  }

  function runSearch(): void {
    const query = input.value;
    if (!query.trim()) {
      if (mode !== 'search') { showAllNotes(); return; }
      countEl.textContent = allNotes.length > 0 ? `${allNotes.length} note${allNotes.length !== 1 ? 's' : ''}` : '';
      countEl.classList.remove('error');
      resultsEl.innerHTML = '<p class="global-search-status">Type to search…</p>';
      currentMatches = [];
      return;
    }
    const matches = performSearch(query, gsRegexMode, allNotes);
    if (matches === null) {
      countEl.textContent = 'invalid regex';
      countEl.classList.add('error');
      return;
    }
    countEl.textContent = `${matches.length} match${matches.length !== 1 ? 'es' : ''}`;
    countEl.classList.remove('error');
    renderResults(matches);
  }

  function confirmSelection(withModifier: boolean): void {
    const m = currentMatches[gsSelectedIndex];
    if (!m) return;
    dismiss();
    if (mode === 'search') {
      const route = { screen: 'edit' as const, owner: m.note.owner, repo: m.note.repo, number: m.note.number };
      if (withModifier) {
        window.open(`${location.pathname}${buildHash(route)}`, '_blank');
      } else {
        navigate(route);
      }
    } else if (mode === 'throw') {
      void throwNote(m.note);
    } else {
      void kickCurrentAndLoad(m.note);
    }
  }

  input.addEventListener('input', () => {
    if (gsDebounce) clearTimeout(gsDebounce);
    if (allNotes.length > 0) gsDebounce = setTimeout(runSearch, 150);
  });

  resultsEl.tabIndex = -1;

  overlay.addEventListener('keydown', (e: KeyboardEvent) => {
    const inInput = e.target === input;
    if (e.key === 'Escape') {
      e.preventDefault();
      dismiss();
    } else if (e.key === 'Tab' && !e.shiftKey && inInput) {
      e.preventDefault();
      resultsEl.focus();
    } else if (e.key === 'Tab' && e.shiftKey && e.target === resultsEl) {
      e.preventDefault();
      input.focus();
    } else if (e.key === 'ArrowDown' || (e.key === 'j' && !inInput)) {
      e.preventDefault();
      if (currentMatches.length > 0) {
        gsSelectedIndex = Math.min(gsSelectedIndex + 1, currentMatches.length - 1);
        updateSelection();
      }
    } else if (e.key === 'ArrowUp' || (e.key === 'k' && !inInput)) {
      e.preventDefault();
      if (gsSelectedIndex > 0) { gsSelectedIndex--; updateSelection(); }
    } else if (e.key === 'Enter') {
      e.preventDefault();
      confirmSelection(e.ctrlKey || e.metaKey);
    } else if (e.key === 'r' && e.ctrlKey) {
      e.preventDefault();
      gsRegexMode = !gsRegexMode;
      updateRegexBtn();
      if (allNotes.length > 0) runSearch();
    }
  });

  overlay.addEventListener('click', (e) => {
    if (e.target === overlay) dismiss();
  });

  regexBtn.addEventListener('click', () => {
    gsRegexMode = !gsRegexMode;
    updateRegexBtn();
    if (allNotes.length > 0) runSearch();
  });

  searchNotes(state.host, state.token)
    .then(notes => {
      allNotes = notes;
      if (input.value.trim()) {
        runSearch();
      } else if (mode !== 'search') {
        showAllNotes();
      } else {
        countEl.textContent = `${notes.length} note${notes.length !== 1 ? 's' : ''}`;
        resultsEl.innerHTML = '<p class="global-search-status">Type to search…</p>';
      }
    })
    .catch(err => {
      resultsEl.innerHTML = `<p class="global-search-status error">Failed to load: ${escapeHtml(err instanceof Error ? err.message : String(err))}</p>`;
    });
}

const MD_LINK_RE = /\[([^\]]*)\]\((https?:\/\/[^)\s]+)\)/g;
const URL_RE = /https?:\/\/[^\s<>"')\]]+/g;

/** Strip [title](url) decoration, leaving the bare URLs behind. */
function stripLinkDecoration(text: string): string {
  return text.replace(MD_LINK_RE, '$2');
}

/** All bare URLs in the text, in order, deduplicated. */
function extractUrls(text: string): string[] {
  const out: string[] = [];
  const seen = new Set<string>();
  for (const m of stripLinkDecoration(text).matchAll(URL_RE)) {
    const url = m[0].replace(/[.,;:!?)]+$/, '');
    if (url && !seen.has(url)) { seen.add(url); out.push(url); }
  }
  return out;
}

function renderEditor(title: string, body: string, buf: NoteBuffer | null): void {  cleanupListKeys?.();
  cleanupListKeys = null;

  const note = buf?.note ?? null;

  app.innerHTML = `
    <div class="editor-screen">
      <header>
        <button id="back-to-list" title="Back to notes">&larr;</button>
        <div id="note-title-container"></div>
        <span id="note-number">${note ? noteNumberHtml(state!.host, note.owner, note.repo, note.number) : 'Title'}</span>
        ${note ? `<button id="copy-note-url" class="copy-url-btn" title="Copy URL">${clipboardIcon}</button>` : ''}
        ${note ? `<button id="attachment-toggle-btn" class="attachment-toggle-btn" title="Attachments (ga)">${paperclipIcon}</button>` : ''}
        ${note ? `<button id="screen-capture-btn" class="screen-capture-btn" title="Screen capture (gS)">${cameraIcon}</button>` : ''}
        ${note ? `<button id="delete-note-btn" class="delete-note-btn" title="Delete note">${xIcon}</button>` : ''}
        <span id="status-msg"></span>
      </header>
      <div id="editor-container"></div>
    </div>
  `;

  document.getElementById('back-to-list')!.addEventListener('click', () => {
    veditor.requestQuit();
  });

  const copyBtn = document.getElementById('copy-note-url');
  if (copyBtn && note) {
    const n = note;
    copyBtn.addEventListener('click', () => {
      showCopyMenu(
        copyBtn as HTMLElement,
        notehubUrl(n.owner, n.repo, n.number),
        issueUrl(state!.host, n.owner, n.repo, n.number),
      );
    });
  }

  document.getElementById('attachment-toggle-btn')?.addEventListener('click', () => toggleAttachmentPanel());
  document.getElementById('screen-capture-btn')?.addEventListener('click', () => handleScreenCapture());
  document.getElementById('delete-note-btn')?.addEventListener('click', () => handleDelete());

  titleHandle = veditor.createVimInput(
    document.getElementById('note-title-container')!,
    {
      value: title,
      onEnter: () => veditor.focusEditor(),
      onEscape: () => veditor.focusEditor(),
      storagePrefix: 'notehub',
    },
  );

  const initialCallbacks = makeBufferCallbacks(
    () => activeNoteKey ? (noteBuffers.get(activeNoteKey) ?? null) : null,
  );

  veditor.createEditor(document.getElementById('editor-container')!, body, initialCallbacks, {
    storagePrefix: 'notehub',
    autoSaveMs: veditor.getAutoSaveMs(),
    initialBufferId: activeNoteKey ?? undefined,
    initialBufferLabel: title,
    normalMappings: {
      'gt': () => titleHandle!.focus(),
      'ga': () => toggleAttachmentPanel(),
      'gS': () => handleScreenCapture(),
      'gs': () => showNotePicker('search'),
      'gT': () => showNotePicker('throw'),
      'gk': () => showNotePicker('kick'),
    },
    exCommands: {
      throw: () => showNotePicker('throw'),
      kick: () => showNotePicker('kick'),
    },
    helpSections: [
      {
        title: 'notehub — Normal mode',
        entries: [
          ['gt', 'Focus title input'],
          ['ga', 'Toggle attachment panel'],
          ['gS', 'Screen capture'],
          ['gs', 'Search all notes'],
          ['gT', 'Throw a note into a new tab (:throw)'],
          ['gk', 'Kick current note to a new tab, load another (:kick)'],
        ],
      },
      {
        title: 'notehub — Note list (outside editor)',
        entries: [
          ['j / k', 'Navigate notes'],
          ['n', 'New note'],
          ['r', 'Refresh note list'],
          ['/', 'Open search bar'],
        ],
      },
    ],
  });

  // Intercept image pastes: upload to attachments repo and insert markdown ref
  document.getElementById('editor-container')!.addEventListener('paste', (e: ClipboardEvent) => {
    const items = e.clipboardData?.items;
    if (!items) return;
    for (const item of Array.from(items)) {
      if (item.type.startsWith('image/')) {
        e.preventDefault();
        const blob = item.getAsFile();
        if (!blob) return;
        const ext = item.type.split('/')[1] || 'png';
        const ts = new Date().toISOString().replace(/[:.]/g, '-');
        const file = new File([blob], `screenshot-${ts}.${ext}`, { type: item.type });
        uploadAndInsertImage(file).catch(err => showStatus(`Screenshot upload failed: ${err instanceof Error ? err.message : err}`, true));
        return;
      }
    }
  });

  // Intercept URL drops (e.g. dragged from the browser address bar): insert
  // each bare URL on its own new line below the cursor's line. The drop text
  // is regex-scanned for URLs rather than trusted as-is, so any
  // [title](url) decoration applied outside our code is stripped. Only
  // claimed when the drop carries nothing but URLs — anything else falls
  // through to the default handler.
  document.getElementById('editor-container')!.addEventListener('drop', (e: DragEvent) => {
    const dt = e.dataTransfer;
    if (!dt || dt.files.length > 0) return;  // attachment flow owns file drops
    const text = dt.getData('text/uri-list') || dt.getData('text/plain');
    if (!text) return;
    const urls = extractUrls(text);
    if (urls.length === 0) return;
    if (stripLinkDecoration(text).replace(URL_RE, '').trim() !== '') return;
    // The deployed veditor bundle may predate insertLineBelowCursor; fall
    // through to CodeMirror's default drop when it's unavailable.
    if (typeof veditor.insertLineBelowCursor !== 'function') return;
    e.preventDefault();
    e.stopPropagation();
    for (const url of urls) veditor.insertLineBelowCursor(url);
  }, { capture: true });

  // Auto-open attachment panel if the note already has attachments
  if (note) {
    const ar = getAttachmentsRepo();
    if (ar) {
      listAttachments(state!.host, state!.token, ar.owner, ar.repo, note.owner, note.repo, note.number)
        .then(attachments => {
          if (attachments.length > 0 && document.querySelector('.editor-screen')) {
            openAttachmentPanel(attachments, { skipFocus: true });
          }
        })
        .catch(() => {});
    }
  }
}


async function handleDelete(): Promise<void> {
  if (!state) return;
  const buf = activeBuffer();
  if (!buf) return;

  const confirmed = confirm(`Delete note "#${buf.note.number}: ${buf.originalTitle}"?`);
  if (!confirmed) return;

  try {
    showStatus('Deleting...');
    const result = await archiveNote(state.host, state.token, buf.note.owner, buf.note.repo, buf.note.number);

    if (result.state !== 'closed') {
      const msg = 'Delete failed: note was not closed';
      showStatus(msg, true);
      logError(msg);
      return;
    }

    logInfo(`Deleted note #${buf.note.number}: ${buf.originalTitle}`);
    showStatus('Deleted');
    setTimeout(() => { navigate({ screen: 'list' }); }, 500);
  } catch (err) {
    const msg = `Delete failed: ${err instanceof Error ? err.message : err}`;
    showStatus(msg, true);
    logError(msg);
  }
}

