function showConflictDialog(): Promise<boolean> {
  return new Promise((resolve) => {
    const overlay = document.createElement('div');
    overlay.id = 'conflict-overlay';
    overlay.innerHTML = `
      <div class="conflict-dialog">
        <h3>Note changed</h3>
        <p>This note has been modified since you opened it. Saving will overwrite those changes.</p>
        <div class="conflict-actions">
          <button id="conflict-cancel">Cancel</button>
          <button id="conflict-overwrite" class="danger">Overwrite</button>
        </div>
      </div>
    `;
    document.body.appendChild(overlay);

    const cleanup = (result: boolean) => {
      overlay.remove();
      document.removeEventListener('keydown', keyHandler);
      resolve(result);
    };

    function keyHandler(e: KeyboardEvent): void {
      if (e.key === 'Escape') cleanup(false);
    }

    overlay.querySelector('#conflict-cancel')!.addEventListener('click', () => cleanup(false));
    overlay.querySelector('#conflict-overwrite')!.addEventListener('click', () => cleanup(true));
    overlay.addEventListener('click', (e) => {
      if (e.target === overlay) cleanup(false);
    });
    document.addEventListener('keydown', keyHandler);
  });
}

// ---------------------------------------------------------------------------
// Attachment Panel
// ---------------------------------------------------------------------------

function toggleAttachmentPanel(): void {
  if (document.getElementById('attachment-panel')) {
    closeAttachmentPanel();
  } else {
    openAttachmentPanel();
  }
}

function closeAttachmentPanel(): void {
  closeAttachmentContextMenu();
  document.getElementById('attachment-panel')?.remove();
  currentAttachments = [];
  selectedAttachmentIndex = 0;
  multiSelectedAttachments.clear();
  thumbLoadGeneration++;
  for (const url of thumbObjectUrls.values()) URL.revokeObjectURL(url);
  thumbObjectUrls.clear();
  veditor?.focusEditor();
}

async function openAttachmentPanel(prefetchedAttachments?: Attachment[], opts?: { skipFocus?: boolean }): Promise<void> {
  const buf = activeBuffer();
  if (!buf || !state) return;

  const editorScreen = document.querySelector('.editor-screen');
  if (!editorScreen) return;

  const currentNote = buf.note;

  // Build repo link for header
  const ar = getAttachmentsRepo();
  const repoLink = ar && state && currentNote
    ? `https://${state.host}/${ar.owner}/${ar.repo}/tree/main/${currentNote.owner}/${currentNote.repo}/${currentNote.number}`
    : '';

  const panel = document.createElement('div');
  panel.id = 'attachment-panel';
  panel.className = 'attachment-panel' + (attachmentViewMode === 'grid' ? ' attachment-panel-grid' : '');
  panel.tabIndex = 0;
  panel.innerHTML = `
    <div class="attachment-panel-header">
      <span class="attachment-panel-title">
        ${paperclipIcon} Attachments
        ${repoLink ? `<a href="${repoLink}" target="_blank" class="attachment-repo-link" title="Open attachments folder on GitHub">\u2197</a>` : ''}
      </span>
      <button id="attachment-close-btn" class="attachment-close-btn" title="Close (Esc)">\u2715</button>
    </div>
    <div id="attachment-list" class="attachment-list"><p class="attachment-loading">Loading...</p></div>
    <div class="attachment-panel-footer">
      <span class="footer-action" data-action="navigate"><kbd>j</kbd><kbd>k</kbd> Nav</span>
      <span class="footer-action" data-action="select"><kbd>Space</kbd> Select</span>
      <span class="footer-action" data-action="view"><kbd>v</kbd> <span id="attach-view-label">Grid</span></span>
      <span class="footer-action" data-action="upload"><kbd>a</kbd> Upload</span>
      <span class="footer-action" data-action="download"><kbd>Enter</kbd> Download</span>
      <span class="footer-action" data-action="preview"><kbd>p</kbd> Preview</span>
      <span class="footer-action" data-action="copylink"><kbd>y</kbd> Copy link</span>
      <span class="footer-action" data-action="delete"><kbd>x</kbd> Delete</span>
      <span class="footer-action" data-action="close"><kbd>Esc</kbd> Close</span>
    </div>
  `;

  editorScreen.appendChild(panel);
  updateViewToggleChip();
  if (!opts?.skipFocus) panel.focus();

  document.getElementById('attachment-close-btn')!.addEventListener('click', (e) => {
    e.stopPropagation();
    closeAttachmentPanel();
  });

  // Clickable footer actions
  panel.querySelectorAll('.footer-action[data-action]').forEach(el => {
    const action = (el as HTMLElement).dataset.action;
    if (action === 'navigate') return; // j/k not meaningful as click
    (el as HTMLElement).style.cursor = 'pointer';
    el.addEventListener('click', async (e) => {
      e.stopPropagation();
      if (action === 'select') toggleMultiSelect();
      else if (action === 'view') toggleAttachmentView();
      else if (action === 'upload') await handleAttachmentUpload();
      else if (action === 'download') await downloadSelectedAttachment();
      else if (action === 'preview') await previewSelectedAttachment();
      else if (action === 'copylink') await copySelectedAttachmentLinks();
      else if (action === 'delete') await deleteSelectedAttachments();
      else if (action === 'close') closeAttachmentPanel();
      panel.focus();
    });
  });

  panel.addEventListener('keydown', async (e: KeyboardEvent) => {
    if (e.key === 'Escape') {
      e.preventDefault();
      closeAttachmentPanel();
    } else if (e.key === 'j' || e.key === 'ArrowDown') {
      e.preventDefault();
      moveAttachmentSelection(1);
    } else if (e.key === 'k' || e.key === 'ArrowUp') {
      e.preventDefault();
      moveAttachmentSelection(-1);
    } else if (e.key === 'a') {
      e.preventDefault();
      await handleAttachmentUpload();
    } else if (e.key === 'Enter' || e.key === 'd') {
      e.preventDefault();
      await downloadSelectedAttachment();
    } else if (e.key === 'p') {
      e.preventDefault();
      await previewSelectedAttachment();
    } else if (e.key === ' ') {
      e.preventDefault();
      toggleMultiSelect();
    } else if (e.key === 'v' && !e.ctrlKey && !e.metaKey) {
      e.preventDefault();
      toggleAttachmentView();
    } else if (e.key === 'y' && !e.ctrlKey && !e.metaKey) {
      e.preventDefault();
      await copySelectedAttachmentLinks();
    } else if (e.key === 'x') {
      e.preventDefault();
      await deleteSelectedAttachments();
    }
  });

  // Paste an image (e.g. a Win+Shift+S screenshot) directly into the panel to
  // upload it as an attachment. Reads from the paste event's own clipboardData,
  // so it needs no clipboard permission and is unaffected by cross-origin rules.
  panel.addEventListener('paste', (e: ClipboardEvent) => {
    const items = e.clipboardData?.items;
    if (!items) return;
    for (const item of Array.from(items)) {
      if (item.type.startsWith('image/')) {
        e.preventDefault();
        const blob = item.getAsFile();
        if (!blob) return;
        const ext = item.type.split('/')[1] || 'png';
        const ts = new Date().toISOString().replace(/[:.]/g, '-');
        const file = new File([blob], `pasted-${ts}.${ext}`, { type: item.type });
        void uploadFiles([file]);
        return;
      }
    }
  });

  panel.addEventListener('dragover', (e: DragEvent) => {
    e.preventDefault();
    panel.classList.add('attachment-panel-dragover');
  });
  panel.addEventListener('dragleave', () => {
    panel.classList.remove('attachment-panel-dragover');
  });
  panel.addEventListener('drop', async (e: DragEvent) => {
    e.preventDefault();
    panel.classList.remove('attachment-panel-dragover');
    const files = Array.from(e.dataTransfer?.files || []);
    if (files.length > 0) await uploadFiles(files);
  });

  await refreshAttachmentList(prefetchedAttachments);
}

async function refreshAttachmentList(prefetched?: Attachment[]): Promise<void> {
  const buf = activeBuffer();
  if (!buf || !state) return;
  const listEl = document.getElementById('attachment-list');
  if (!listEl) return;

  if (prefetched) {
    currentAttachments = prefetched;
    buf.attachments = currentAttachments;
  } else {
    const ar = await ensureAttachmentRepo();
    if (!ar) {
      listEl.innerHTML = '<p class="attachment-error">Attachments repo not available.</p>';
      return;
    }

    try {
      currentAttachments = await listAttachments(
        state.host, state.token, ar.owner, ar.repo, buf.note.owner, buf.note.repo, buf.note.number,
      );
      buf.attachments = currentAttachments;
    } catch (err) {
      listEl.innerHTML = `<p class="attachment-error">Failed to load: ${err instanceof Error ? err.message : err}</p>`;
      return;
    }
  }

  selectedAttachmentIndex = 0;
  buf.selectedAttachmentIndex = 0;
  renderAttachmentList(listEl);
}

const IMAGE_EXTS = new Set(['jpg', 'jpeg', 'png', 'gif', 'webp', 'svg', 'bmp', 'avif']);

function isImageAttachment(name: string): boolean {
  return IMAGE_EXTS.has(name.split('.').pop()?.toLowerCase() ?? '');
}

// Full (re)build of the attachment area for the current view mode. Attaches
// event handlers exactly once per build; selection changes afterward go through
// the lightweight updateAttachmentSelection() (class toggles only), so we never
// tear down and rebuild rows/tiles \u2014 and their <img> elements \u2014 on every j/k.
function renderAttachmentList(listEl: HTMLElement): void {
  if (currentAttachments.length === 0) {
    listEl.className = 'attachment-list';
    listEl.innerHTML = '<p class="attachment-empty">No attachments yet. Press <kbd>a</kbd> to upload.</p>';
    return;
  }
  if (attachmentViewMode === 'grid') renderAttachmentGrid(listEl);
  else renderAttachmentRows(listEl);
}

function renderAttachmentRows(listEl: HTMLElement): void {
  listEl.className = 'attachment-list';
  listEl.innerHTML = currentAttachments.map((a, i) => {
    const classes = ['attachment-row', i === selectedAttachmentIndex ? 'selected' : '', multiSelectedAttachments.has(i) ? 'multi-selected' : ''].filter(Boolean).join(' ');
    return `
    <div class="${classes}" data-index="${i}">
      <span class="attachment-checkbox">${multiSelectedAttachments.has(i) ? '\u2611' : '\u2610'}</span>
      <span class="attachment-name" title="Click to preview, Ctrl+click to download">${escapeHtml(a.name)}</span>
      <span class="attachment-size">${formatAttachmentSize(a.size)}</span>
    </div>`;
  }).join('');
  attachSelectionHandlers(listEl);
  updateAttachmentSelection(listEl);
}

function renderAttachmentGrid(listEl: HTMLElement): void {
  listEl.className = 'attachment-list attachment-grid';
  listEl.innerHTML = currentAttachments.map((a, i) => {
    const classes = ['attachment-tile', i === selectedAttachmentIndex ? 'selected' : '', multiSelectedAttachments.has(i) ? 'multi-selected' : ''].filter(Boolean).join(' ');
    const ext = (a.name.split('.').pop() ?? '').toUpperCase();
    const thumb = isImageAttachment(a.name)
      ? `<div class="attachment-thumb" title="Click to preview, Ctrl+click to download"><span class="attachment-thumb-spinner">\u2026</span></div>`
      : `<div class="attachment-thumb attachment-thumb-file" title="Click to preview, Ctrl+click to download"><span class="attachment-file-ext">${escapeHtml(ext || 'FILE')}</span></div>`;
    return `
    <div class="${classes}" data-index="${i}">
      <span class="attachment-checkbox">${multiSelectedAttachments.has(i) ? '\u2611' : '\u2610'}</span>
      ${thumb}
      <span class="attachment-name attachment-tile-caption" title="${escapeAttr(a.name)}">${escapeHtml(a.name)}</span>
    </div>`;
  }).join('');
  attachSelectionHandlers(listEl);
  updateAttachmentSelection(listEl);
  loadGridThumbnails(listEl);
}

// Wire click handlers once per full build. Works for both rows and tiles via
// the shared [data-index] / .attachment-checkbox / .attachment-name contract;
// the thumbnail area also triggers preview/download.
function attachSelectionHandlers(listEl: HTMLElement): void {
  // Track whether the panel had focus before this mousedown (a click steals it).
  let panelHadFocus = false;
  const panel = document.getElementById('attachment-panel');
  listEl.addEventListener('mousedown', () => {
    panelHadFocus = panel === document.activeElement;
  });

  listEl.querySelectorAll<HTMLElement>('[data-index]').forEach(item => {
    const idx = parseInt(item.dataset.index!, 10);

    item.querySelector('.attachment-checkbox')?.addEventListener('click', (e) => {
      e.stopPropagation();
      if (!panelHadFocus) { panel?.focus(); return; }
      selectedAttachmentIndex = idx;
      if (multiSelectedAttachments.has(idx)) multiSelectedAttachments.delete(idx);
      else multiSelectedAttachments.add(idx);
      updateAttachmentSelection(listEl);
      panel?.focus();
    });

    // Name (and thumbnail) click: Ctrl/Cmd+click downloads, plain click previews.
    item.querySelectorAll('.attachment-name, .attachment-thumb').forEach(el => {
      el.addEventListener('click', async (e) => {
        e.stopPropagation();
        if (!panelHadFocus) { panel?.focus(); return; }
        selectedAttachmentIndex = idx;
        updateAttachmentSelection(listEl);
        if ((e as MouseEvent).ctrlKey || (e as MouseEvent).metaKey) {
          await downloadAttachmentByIndex(idx);
        } else {
          await previewSelectedAttachment();
        }
        panel?.focus();
      });
    });

    // Click elsewhere on the row/tile: focus-only if unfocused, else move cursor.
    item.addEventListener('click', () => {
      if (!panelHadFocus) { panel?.focus(); return; }
      selectedAttachmentIndex = idx;
      updateAttachmentSelection(listEl);
      panel?.focus();
    });

    // Right-click: our own menu with browser-worthy links. Acts on the whole
    // multi-selection if the target is part of it, else on just this item.
    item.addEventListener('contextmenu', (e) => {
      e.preventDefault();
      const inMulti = multiSelectedAttachments.has(idx);
      const indices = inMulti ? [...multiSelectedAttachments].sort((a, b) => a - b) : [idx];
      if (!inMulti) {
        selectedAttachmentIndex = idx;
        updateAttachmentSelection(listEl);
      }
      showAttachmentContextMenu((e as MouseEvent).clientX, (e as MouseEvent).clientY, indices);
    });
  });
}

// Lightweight selection update \u2014 toggles classes/checkbox glyphs only, no DOM
// teardown. Safe to call on every navigation keystroke.
function updateAttachmentSelection(listEl: HTMLElement): void {
  listEl.querySelectorAll<HTMLElement>('[data-index]').forEach(item => {
    const idx = parseInt(item.dataset.index!, 10);
    const isMulti = multiSelectedAttachments.has(idx);
    item.classList.toggle('selected', idx === selectedAttachmentIndex);
    item.classList.toggle('multi-selected', isMulti);
    const cb = item.querySelector('.attachment-checkbox');
    if (cb) cb.textContent = isMulti ? '\u2611' : '\u2610';
  });
  listEl.querySelector<HTMLElement>('[data-index].selected')?.scrollIntoView({ block: 'nearest' });
}

// Browser-worthy link to a file's GitHub/GHES "blob" page — i.e. what you'd get
// by putting the file's path in the URL bar. Points at the PRIVATE attachments
// repo, so it resolves only in a browser authenticated to that repo (accepted).
function attachmentBlobUrl(a: Attachment | undefined): string | null {
  if (!a || !state) return null;
  const ar = getAttachmentsRepo();
  if (!ar) return null;
  return `https://${state.host}/${ar.owner}/${ar.repo}/blob/main/${a.path}`;
}

function attachmentsFolderUrl(): string | null {
  const buf = activeBuffer();
  const ar = getAttachmentsRepo();
  if (!buf || !ar || !state) return null;
  const n = buf.note;
  return `https://${state.host}/${ar.owner}/${ar.repo}/tree/main/${n.owner}/${n.repo}/${n.number}`;
}

async function copyAttachmentLinks(indices: number[]): Promise<void> {
  const urls = indices
    .map(i => attachmentBlobUrl(currentAttachments[i]))
    .filter((u): u is string => !!u);
  if (urls.length === 0) return;
  try {
    await copyText(urls.join('\n'));
    showStatus(urls.length === 1 ? 'Link copied' : `${urls.length} links copied`);
  } catch (err) {
    showStatus(`Copy failed: ${err instanceof Error ? err.message : err}`, true);
  }
}

// Copy links for the active selection: the multi-selection if any, else the cursor.
async function copySelectedAttachmentLinks(): Promise<void> {
  const indices = multiSelectedAttachments.size > 0
    ? [...multiSelectedAttachments].sort((a, b) => a - b)
    : [selectedAttachmentIndex];
  await copyAttachmentLinks(indices);
}

// --- Attachment right-click context menu ---------------------------------
// The menu is appended to <body> with fixed positioning so the panel's
// overflow:auto never clips it, and torn down on outside-click/Esc/scroll/resize.

function closeAttachmentContextMenu(): void {
  document.getElementById('attachment-context-menu')?.remove();
  document.removeEventListener('keydown', onContextMenuKeydown, true);
  document.removeEventListener('click', closeAttachmentContextMenu);
  window.removeEventListener('scroll', closeAttachmentContextMenu, true);
  window.removeEventListener('resize', closeAttachmentContextMenu);
}

function onContextMenuKeydown(e: KeyboardEvent): void {
  if (e.key === 'Escape') {
    e.preventDefault();
    e.stopPropagation(); // don't let the panel's Esc handler also close the panel
    closeAttachmentContextMenu();
    document.getElementById('attachment-panel')?.focus();
  }
}

function showAttachmentContextMenu(x: number, y: number, indices: number[]): void {
  closeAttachmentContextMenu();
  const n = indices.length;
  const actions: { label: string; run: () => void | Promise<void> }[] = [
    { label: n > 1 ? `Copy ${n} links` : 'Copy link', run: () => copyAttachmentLinks(indices) },
  ];
  if (n === 1) {
    const url = attachmentBlobUrl(currentAttachments[indices[0]]);
    if (url) actions.push({ label: 'Open in GitHub', run: () => { window.open(url, '_blank'); } });
  } else {
    const folder = attachmentsFolderUrl();
    if (folder) actions.push({ label: 'Open folder in GitHub', run: () => { window.open(folder, '_blank'); } });
  }

  const menu = document.createElement('div');
  menu.id = 'attachment-context-menu';
  menu.className = 'attachment-context-menu';
  menu.innerHTML = actions
    .map((a, i) => `<button class="attachment-context-item" data-i="${i}">${escapeHtml(a.label)}</button>`)
    .join('');
  document.body.appendChild(menu);

  // Clamp into the viewport.
  const rect = menu.getBoundingClientRect();
  menu.style.left = `${Math.max(4, Math.min(x, window.innerWidth - rect.width - 4))}px`;
  menu.style.top = `${Math.max(4, Math.min(y, window.innerHeight - rect.height - 4))}px`;

  menu.querySelectorAll<HTMLButtonElement>('.attachment-context-item').forEach(btn => {
    btn.addEventListener('click', async (e) => {
      e.stopPropagation(); // keep the outside-click closer from firing first
      closeAttachmentContextMenu();
      await actions[parseInt(btn.dataset.i!, 10)].run();
      document.getElementById('attachment-panel')?.focus();
    });
  });

  // Defer the outside-click listener so the current event doesn't instantly close it.
  setTimeout(() => document.addEventListener('click', closeAttachmentContextMenu), 0);
  document.addEventListener('keydown', onContextMenuKeydown, true);
  window.addEventListener('scroll', closeAttachmentContextMenu, true);
  window.addEventListener('resize', closeAttachmentContextMenu);
}

// Simple concurrency-limited runner: process items with at most `limit` in
// flight at once. Keeps the burst of contents-API calls polite on grid open.
async function runPool<T>(items: T[], worker: (item: T) => Promise<void>, limit = 4): Promise<void> {
  let next = 0;
  const runNext = async (): Promise<void> => {
    const idx = next++;
    if (idx >= items.length) return;
    await worker(items[idx]);
    return runNext();
  };
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, runNext));
}

// Fetch image bytes for an attachment, cache-first (IndexedDB keyed by sha).
async function loadThumbBlob(a: Attachment): Promise<Blob | null> {
  const cached = await getThumb(a.sha);
  if (cached) return cached;
  const ar = getAttachmentsRepo();
  if (!ar || !state) return null;
  const { blob } = await fetchAttachmentBlob(state.host, state.token, ar.owner, ar.repo, a.path);
  await putThumb(a.sha, blob);
  return blob;
}

// Populate the <img> thumbnails for image tiles in the current grid build.
function loadGridThumbnails(listEl: HTMLElement): void {
  const myGen = ++thumbLoadGeneration;
  const images = currentAttachments
    .map((a, i) => ({ a, i }))
    .filter(({ a }) => isImageAttachment(a.name));

  const setImg = (thumb: HTMLElement, url: string, alt: string): void => {
    const img = document.createElement('img');
    img.className = 'attachment-thumb-img';
    img.alt = alt;
    img.src = url;
    img.onerror = () => {
      thumb.classList.add('attachment-thumb-file');
      thumb.innerHTML = '<span class="attachment-file-ext">IMG</span>';
    };
    thumb.innerHTML = '';
    thumb.appendChild(img);
  };

  void runPool(images, async ({ a, i }) => {
    if (myGen !== thumbLoadGeneration) return; // grid rebuilt/closed since
    const thumb = listEl.querySelector<HTMLElement>(`[data-index="${i}"] .attachment-thumb`);
    if (!thumb || !document.body.contains(thumb)) return;

    // Reuse a session object URL if we already minted one for these bytes.
    const existing = thumbObjectUrls.get(a.sha);
    if (existing) { setImg(thumb, existing, a.name); return; }

    try {
      const blob = await loadThumbBlob(a);
      if (!blob || myGen !== thumbLoadGeneration || !document.body.contains(thumb)) return;
      let url = thumbObjectUrls.get(a.sha);
      if (!url) { url = URL.createObjectURL(blob); thumbObjectUrls.set(a.sha, url); }
      setImg(thumb, url, a.name);
    } catch {
      thumb.classList.add('attachment-thumb-file');
      thumb.innerHTML = '<span class="attachment-file-ext">ERR</span>';
    }
  }, 4);
}

